import hashlib, base64, re, os, glob, struct, json, urllib.request
salt = bytes.fromhex("518D64A635DED8C1E6B039B1C3E55230")
def nid(name):
    d = hashlib.sha1(name.encode() + salt).digest()[:8]
    v = struct.unpack("<Q", d)[0]
    s = base64.b64encode(struct.pack(">Q", v)).decode().rstrip("=")
    return s.replace("/", "-")
print("check", nid("_ZnamSt11align_val_tRKSt9nothrow_t"), "want s2eGsgUF9vk")
stubs = {}
for f in glob.glob("core/libs/prx/**/*.cpp", recursive=True):
    if "/tests/" in f: continue
    txt = open(f, errors="ignore").read()
    pos = 0
    for m in re.finditer(r'APS5_EXPORT\("([^"]+)",\s*(\w+)\)', txt):
        chunk = txt[pos:m.start()]; pos = m.end()
        if "NotImplemented" in chunk:
            stubs.setdefault(m.group(1), []).append((f, m.group(2)))
print("stub NIDs", len(stubs))
impl = {}
for f in glob.glob("core/libs/prx/**/*.cpp", recursive=True):
    if "/tests/" in f: continue
    txt = open(f, errors="ignore").read()
    for m in re.finditer(r'\b(\w+)_nid_postfix\s*\(([^)]*)\)\s*(noexcept)?\s*\{', txt):
        name = m.group(1)
        body = txt[m.end():m.end()+400]
        if "NotImplemented" in body.split("\n}")[0]: continue
        impl.setdefault(name, f)
print("implemented postfix names", len(impl))
hits = []
for name, f in impl.items():
    n = nid(name)
    if n in stubs:
        for sf, fn in stubs[n]:
            lib_s = sf.split("/")[3]; lib_i = f.split("/")[3]
            hits.append((lib_s, n, name, sf, fn, f))
hits.sort()
for h in hits: print("HIT", *h)
open("/tmp/hits.json","w").write(json.dumps(hits))
